1|import "server-only";
2|import { createHash, timingSafeEqual } from "node:crypto";
3|import type { KV } from "@/core/types";
4|import { FRIEND_CODE_MAX_LEN } from "@/core/uploads";
5|import { hashIp, ipBucket } from "./request";
6|
7|// Per-person quota, counted by hashed IP and by the anonymous
8|// cookie, whichever runs out first. Day keys are UTC dates.
9|export const CHAT_QUOTA_TTL_SEC = 48 * 3600;
10|
11|export interface DualKeys {
12|  ip: string;
13|  anon: string;
14|}
15|
16|export async function takeDualQuota(
17|  kv: KV,
18|  keys: DualKeys,
19|  opts: { limit: number; ttlSec: number },
20|): Promise<{ ok: true; ipCount: number; anonCount: number } | { ok: false }> {
21|  let ipTaken = false;
22|  let anonTaken = false;
23|  try {
24|    const ipCount = await kv.incr(keys.ip);
25|    ipTaken = true;
26|    await kv.expire(keys.ip, opts.ttlSec);
27|    const anonCount = await kv.incr(keys.anon);
28|    anonTaken = true;
29|    await kv.expire(keys.anon, opts.ttlSec);
30|    if (ipCount > opts.limit || anonCount > opts.limit) {
31|      // Compensating decrs are best effort: a Redis failure here must
32|      // neither throw nor leak the caller's counts, so each stands alone.
33|      try {
34|        await kv.decr(keys.ip);
35|      } catch {
36|        // The increment already landed; the TTL bounds the damage.
37|      }
38|      try {
39|        await kv.decr(keys.anon);
40|      } catch {
41|        // The increment already landed; the TTL bounds the damage.
42|      }
43|      return { ok: false };
44|    }
45|    return { ok: true, ipCount, anonCount };
46|  } catch (e) {
47|    // A Redis failure between increments gives back what landed, so a
48|    // timeout never leaks quota. Best effort, then the caller maps it.
49|    if (anonTaken) {
50|      try {
51|        await kv.decr(keys.anon);
52|      } catch {
53|        // The increment already landed; the TTL bounds the damage.
54|      }
55|    }
56|    if (ipTaken) {
57|      try {
58|        await kv.decr(keys.ip);
59|      } catch {
60|        // The increment already landed; the TTL bounds the damage.
61|      }
62|    }
63|    throw e;
64|  }
65|}
66|
67|// Best effort: a Redis failure here must never become a client 500.
68|export async function refundDualQuota(kv: KV, keys: DualKeys): Promise<void> {
69|  try {
70|    await kv.decr(keys.ip);
71|    await kv.decr(keys.anon);
72|  } catch {
73|    // Redis down: nothing reserved server-side to retry against.
74|  }
75|}
