77|// Free uploaded-book processing: one book per person per UTC day,
78|// counted on hashed IP and the anon cookie, whichever hits first.
79|export const FREE_BOOKS_PER_PERSON = 1;
80|// A valid friend code raises the free path to five books that day,
81|// on the same quota keys, so a friend gets five total, not five more.
82|export const FRIEND_BOOKS_PER_PERSON = 5;
83|// Wrong friend-code guesses per hashed IP per day before codes stop
84|// being checked; a wrong guess never errors, the upload just keeps
85|// the normal quota.
86|export const FRIEND_WRONG_GUESSES_PER_DAY = 10;
87|// BYOK uploads spend the reader's key, but creates still need a per-person
88|// cap so a bot cannot farm infinite jobs; same dual counting, own prefix.
89|export const BYOK_UPLOADS_PER_PERSON = 10;
90|export const BOOK_QUOTA_TTL_SEC = 48 * 3600;
91|
92|export function bookQuotaKeys(args: { day: string; ipHash: string; anonId: string; prefix?: string }): DualKeys {
93|  const prefix = args.prefix ?? "books:quota";
94|  return {
95|    ip: `${prefix}:ip:${args.day}:${args.ipHash}`,
96|    anon: `${prefix}:anon:${args.day}:${args.anonId}`,
97|  };
98|}
99|
100|export function bookQuotaKeysFor(args: {
101|  day: string;
102|  ip: string;
103|  salt: string;
104|  anonId: string;
105|  prefix?: string;
106|}): DualKeys {
107|  return bookQuotaKeys({
108|    day: args.day,
109|    ipHash: hashIp(ipBucket(args.ip, args.anonId), args.salt),
110|    anonId: args.anonId,
111|    prefix: args.prefix,
112|  });
113|}
114|
115|// Thin wrapper so the book hook shares the never-throw compensation.
116|export async function checkBookQuota(
117|  kv: KV,
118|  keys: DualKeys,
119|): Promise<{ ok: true } | { ok: false }> {
120|  const taken = await takeDualQuota(kv, keys, {
121|    limit: FREE_BOOKS_PER_PERSON,
122|    ttlSec: BOOK_QUOTA_TTL_SEC,
123|  });
124|  return taken.ok ? { ok: true } : { ok: false };
125|}
126|
127|export async function refundBookQuota(kv: KV, keys: DualKeys): Promise<void> {
128|  await refundDualQuota(kv, keys);
