131|// Server-only friend codes from LECTORIA_FRIEND_CODES: comma-separated,
132|// trimmed, empties dropped. Unset or empty means the feature is off.
133|export function parseFriendCodes(raw: string | undefined | null): string[] {
134|  if (!raw) return [];
135|  return raw
136|    .split(",")
137|    .map((code) => code.trim())
138|    .filter((code) => code.length > 0);
139|}
140|
141|// Constant-time match over sha256 digests so lengths always match, and
142|// every configured code is checked with no early exit.
143|export function matchFriendCode(submitted: string, codes: string[]): boolean {
144|  const want = createHash("sha256").update(submitted, "utf8").digest();
145|  let hit = false;
146|  for (const code of codes) {
147|    const got = createHash("sha256").update(code, "utf8").digest();
148|    if (timingSafeEqual(want, got)) hit = true;
149|  }
150|  return hit;
151|}
