153|export function friendGuessKeyFor(args: { day: string; ip: string; salt: string; anonId: string }): string {
154|  return `books:friend-guess:ip:${args.day}:${hashIp(ipBucket(args.ip, args.anonId), args.salt)}`;
155|}
