157|// True when the submitted code is valid and the guess budget remains.
158|// Anything else is false, never an error: the upload keeps the normal
159|// quota. Never logs or returns the code itself.
160|export async function acceptFriendCode(
161|  kv: KV,
162|  submitted: unknown,
163|  codes: string[],
164|  guessKey: string,
165|): Promise<boolean> {
166|  if (typeof submitted !== "string") return false;
167|  const code = submitted.trim();
168|  if (code.length === 0 || code.length > FRIEND_CODE_MAX_LEN) return false;
169|  if (codes.length === 0) return false;
170|  let guesses = 0;
171|  try {
172|    const raw = await kv.get(guessKey);
173|    guesses = raw === null ? 0 : Number(raw);
174|    if (!Number.isFinite(guesses) || guesses < 0) guesses = 0;
175|  } catch {
176|    return false; // Redis down: no friend path, the normal quota still applies.
177|  }
178|  if (guesses >= FRIEND_WRONG_GUESSES_PER_DAY) return false;
179|  if (matchFriendCode(code, codes)) return true;
180|  try {
181|    await kv.incr(guessKey);
182|    await kv.expire(guessKey, BOOK_QUOTA_TTL_SEC);
183|  } catch {
184|    // Best effort; the guess just goes uncounted.
185|  }
186|  return false;
