2|import { parseCapUsd, turnstilePair, usable } from "@/server/guard/env";
3|import type { TurnstilePair } from "@/server/guard/env";
4|import { parseFriendCodes } from "@/server/guard/quota";
5|
6|// Upload env, read once per request. Jev is optional: without a usable key
7|// the free path classifies with the contributor model alone. Missing
8|// required env means 503 unavailable, never unauthenticated spend.
9|export interface UploadEnv extends TurnstilePair {
10|  upstashUrl: string;
11|  upstashToken: string;
12|  uploadsToken: string;
13|  metaKey: string;
14|  jevKey?: string;
15|  sessionSecret: string;
16|  ipSalt: string;
17|  spendCapMicro: number;
18|  // Valid friend codes raising the free path to five books a day.
19|  // Empty when LECTORIA_FRIEND_CODES is unset: the feature is off.
20|  friendCodes?: string[];
21|}
22|
23|const URL_NAMES = "UPSTASH_REDIS_REST_URL|KV_REST_API_URL";
24|const TOKEN_NAMES = "UPSTASH_REDIS_REST_TOKEN|KV_REST_API_TOKEN";
25|
26|// The uploads token is its own private store: the image store is public
27|// and a store's access mode is fixed at creation, so private puts would
28|// fail against it. Never fall back to the public store.
29|const REQUIRED = [
30|  "UPLOADS_BLOB_READ_WRITE_TOKEN",
31|  "META_API_KEY",
32|  "SESSION_SECRET",
33|  "IP_HASH_SALT",
34|] as const;
35|
36|export function readUploadEnv(from: NodeJS.ProcessEnv = process.env): UploadEnv {
37|  const candidate = usable(from.UPSTASH_REDIS_REST_URL) ?? usable(from.KV_REST_API_URL);
38|  const upstashUrl = candidate?.startsWith("https://") ? candidate : undefined;
39|  const upstashToken = usable(from.UPSTASH_REDIS_REST_TOKEN) ?? usable(from.KV_REST_API_TOKEN);
40|  const missing = [
41|    upstashUrl ? null : URL_NAMES,
42|    upstashToken ? null : TOKEN_NAMES,
43|    ...REQUIRED.filter((k) => !usable(from[k])),
44|  ].filter((m): m is string => m !== null);
45|  if (missing.length > 0) throw new Error(`missing upload env: ${missing.join(",")}`);
46|  const jevKey = usable(from.JEV_API_KEY);
47|  return {
48|    upstashUrl: upstashUrl as string,
49|    upstashToken: upstashToken as string,
50|    uploadsToken: from.UPLOADS_BLOB_READ_WRITE_TOKEN as string,
51|    metaKey: from.META_API_KEY as string,
52|    ...(jevKey ? { jevKey } : {}),
53|    sessionSecret: from.SESSION_SECRET as string,
54|    ipSalt: from.IP_HASH_SALT as string,
55|    spendCapMicro: Math.round(parseCapUsd(from.SPEND_CAP_USD, 10) * 1_000_000),
56|    friendCodes: parseFriendCodes(usable(from.LECTORIA_FRIEND_CODES)),
57|    ...turnstilePair(from),
